    invariant lm.ValidTokensIdsLogits()
    invariant parser.IsValidPrefix(generated)
    invariant generated == currentPrefix + suffix
    invariant |suffix| == steps
    invariant helpers.cost <= steps
    decreases maxSteps - steps
